@test("descriptions")
def _():
    check_eq(Rectangle(3, 4).describe(), "Rectangle: area 12.00, perimeter 14.00")
    check_eq(Square(2).describe(), "Square: area 4.00, perimeter 8.00")
    check_eq(Circle(1).describe(), "Circle: area 3.14, perimeter 6.28")

@test("the hierarchy")
def _():
    check(isinstance(Square(2), Rectangle) and isinstance(Square(2), Shape))
    check(not isinstance(Circle(1), Rectangle))
    check_raises(TypeError, Shape)
    check("describe" not in Rectangle.__dict__ and "describe" not in Circle.__dict__, "describe belongs to Shape only")

@test("largest")
def _():
    shapes = [Square(3), Circle(1.6), Rectangle(2, 4.5)]
    check(largest(shapes) is shapes[0])
    check_eq(largest([]), None)

@test("duck typing")
def _():
    class Plot:
        def area(self):
            return 100
    check_near(total_area([Square(2), Plot(), Circle(1)]), 104 + math.pi)

